def evaluate(player, opponent, college_fellows):
    def valid(allocation):
        return (isinstance(allocation, dict) and set(allocation) == set(college_fellows)
                and all(type(x) is int and x >= 0 for x in allocation.values()) and sum(allocation.values()) <= 100)
    p_valid, o_valid = valid(player), valid(opponent)
    if not p_valid or not o_valid:
        return 0.5 if not p_valid and not o_valid else 1 if p_valid else 0
    p, o = player, opponent
    votes = sum(v for c, v in college_fellows.items() if p[c] > 0 and p[c] >= 2 * o[c])
    opponent_votes = sum(v for c, v in college_fellows.items() if o[c] > 0 and o[c] >= 2 * p[c])
    return 1 if votes > opponent_votes else 0.5 if votes == opponent_votes else 0
